  static Graph G(string id){return new Graph{LevelId=id};} static GraphNode N(string u,string t,float x,float y,params string[] ps){var n=new GraphNode{Uid=u,Type=t,X=x,Y=y};for(int i=0;i+1<ps.Length;i+=2)n.Params[ps[i]]=ps[i+1];return n;} static void E(Graph g,string f,string p,string t){g.Links.Add(new GraphLink{FromNode=f,FromPort=p,ToNode=t,ToPort="in",Kind=LinkKind.Exec});}
