  static Graph L2(){var g=G("L2");g.ExprMode=true;g.Nodes.AddRange(new[]{N("e","entry",20,20),N("declN","vardecl",20,82,"name","n","vtype","int"),N("inN","input",20,190,"vtype","int","name","n"),N("declA","vardecl",20,266,"name","a","vtype","int[]"),N("declX","vardecl",20,374,"name","x","vtype","int","initExpr","0"),N("declSum","vardecl",20,482,"name","sum","vtype","int","initExpr","0"),N("fill","forloop",20,590,"fromExpr","0","toExpr","n - 1","indexName","i"),N("inX","input",250,730,"vtype","int","name","x"),N("wset","varset",250,806,"name","a","valueExpr","a[i] = x"),N("acc","forloop",20,952,"fromExpr","0","toExpr","a.size - 1","indexName","i"),N("add","varset",250,1092,"name","sum","valueExpr","sum + a[i]"),N("out","output",20,1218,"outputExpr","sum"),N("answer","sample_compare",250,1218,"exprMode","1"),N("sample","sample_input",250,20,"group","0")});E(g,"e","out","declN");E(g,"declN","out","inN");E(g,"inN","out","declA");E(g,"declA","out","declX");E(g,"declX","out","declSum");E(g,"declSum","out","fill");E(g,"fill","body","inX");E(g,"inX","out","wset");E(g,"fill","done","acc");E(g,"acc","body","add");E(g,"acc","done","out");return g;}
