  static Graph L3(){var g=G("L3");g.ExprMode=true;g.Structs.Add(new StructDef{Id="st",Kind="stack",Elem="char"});g.Nodes.AddRange(new[]{N("e","entry",20,20),N("new","structnew",20,104,"structId","st"),N("declS","vardecl",20,188,"name","s","vtype","string"),N("ins","input",20,272,"vtype","string","name","s"),N("declOk","vardecl",20,356,"name","ok","vtype","bool","initExpr","true"),N("loop","forloop",20,440,"fromExpr","0","toExpr","s.size - 1","indexName","i"),N("declC","vardecl",250,580,"name","c","vtype","char","initExpr","s[i]"),N("b1","branch",250,664,"condExpr","c == '('"),N("push","stack_push",480,600,"structId","st","pushExpr","c"),N("b2","branch",250,792,"condExpr","c == ')'"),N("b3","branch",250,920,"condExpr","st.empty"),N("setFalse1","varset",250,1048,"name","ok","valueExpr","ok = false"),N("pop","stack_pop",480,860,"structId","st"),N("b4","branch",20,1060,"condExpr","!st.empty"),N("setFalse2","varset",250,1144,"name","ok","valueExpr","ok = false"),N("out","output",20,1240,"outputExpr","ok"),N("sample","sample_input",710,20,"group","0"),N("answer","sample_compare",710,130,"exprMode","1")});E(g,"e","out","new");E(g,"new","out","declS");E(g,"declS","out","ins");E(g,"ins","out","declOk");E(g,"declOk","out","loop");E(g,"loop","body","declC");E(g,"declC","out","b1");E(g,"b1","true","push");E(g,"b1","false","b2");E(g,"b2","true","b3");E(g,"b3","true","setFalse1");E(g,"b3","false","pop");E(g,"loop","done","b4");E(g,"b4","true","setFalse2");E(g,"b4","false","out");E(g,"setFalse2","out","out");return g;}
