  static Graph S1(){var g=G("S1");g.ExprMode=true;g.Structs.Add(new StructDef{Id="st",Kind="stack",Elem="int"});g.Nodes.AddRange(new[]{N("e","entry",20,20),N("new","structnew",20,104,"structId","st"),N("declN","vardecl",20,188,"name","n","vtype","int"),N("inN","input",20,272,"vtype","int","name","n"),N("declX","vardecl",20,356,"name","x","vtype","int","initExpr","0"),N("pushLoop","forloop",20,440,"fromExpr","0","toExpr","n - 1","indexName","i"),N("inX","input",250,580,"vtype","int","name","x"),N("push","stack_push",250,664,"structId","st","pushExpr","x"),N("popLoop","forloop",20,810,"fromExpr","0","toExpr","n - 1","indexName","j"),N("out","output",250,950,"outputExpr","st.top"),N("pop","stack_pop",250,1100,"structId","st"),N("sample","sample_input",710,20,"group","0"),N("answer","sample_compare",710,130,"exprMode","1")});E(g,"e","out","new");E(g,"new","out","declN");E(g,"declN","out","inN");E(g,"inN","out","declX");E(g,"declX","out","pushLoop");E(g,"pushLoop","body","inX");E(g,"inX","out","push");E(g,"pushLoop","done","popLoop");E(g,"popLoop","body","out");E(g,"out","out","pop");return g;}
  // S2 压进去 n 个、拿走最上面的 k 个，最后用「栈顶元素」看一眼、不拿走。k = 0 时第二个循环一圈都不转。
  static Graph S2(){var g=G("S2");g.ExprMode=true;g.Structs.Add(new StructDef{Id="st",Kind="stack",Elem="int"});g.Nodes.AddRange(new[]{N("e","entry",20,20),N("new","structnew",20,104,"structId","st"),N("declN","vardecl",20,188,"name","n","vtype","int"),N("inN","input",20,272,"vtype","int","name","n"),N("declX","vardecl",20,356,"name","x","vtype","int","initExpr","0"),N("pushLoop","forloop",20,440,"fromExpr","0","toExpr","n - 1","indexName","i"),N("inX","input",250,580,"vtype","int","name","x"),N("push","stack_push",250,664,"structId","st","pushExpr","x"),N("declK","vardecl",20,810,"name","k","vtype","int"),N("inK","input",20,894,"vtype","int","name","k"),N("popLoop","forloop",20,978,"fromExpr","0","toExpr","k - 1","indexName","j"),N("pop","stack_pop",250,1118,"structId","st"),N("out","output",20,1264,"outputExpr","st.top"),N("sample","sample_input",710,20,"group","0"),N("answer","sample_compare",710,130,"exprMode","1")});E(g,"e","out","new");E(g,"new","out","declN");E(g,"declN","out","inN");E(g,"inN","out","declX");E(g,"declX","out","pushLoop");E(g,"pushLoop","body","inX");E(g,"inX","out","push");E(g,"pushLoop","done","declK");E(g,"declK","out","inK");E(g,"inK","out","popLoop");E(g,"popLoop","body","pop");E(g,"popLoop","done","out");return g;}
  // S3 队列版：入队 n 个再逐个出队，队头先看后走，输出顺序与读入相同。
