  static Graph L4(){var g=G("L4");g.ExprMode=true;g.Nodes.AddRange(new[]{N("e","entry",20,20),N("declN","vardecl",20,82,"name","n","vtype","int"),N("inN","input",20,190,"vtype","int","name","n"),N("declA","vardecl",20,266,"name","a","vtype","int[]"),N("declX","vardecl",20,374,"name","x","vtype","int","initExpr","0"),N("fill","forloop",20,494,"fromExpr","0","toExpr","n - 1","indexName","i"),N("inX","input",250,634,"vtype","int","name","x"),N("wset","varset",250,710,"name","a","valueExpr","a[i] = x"),N("declM","vardecl",20,850,"name","m","vtype","int","initExpr","a[0]"),N("scan","forloop",20,970,"fromExpr","1","toExpr","n - 1","indexName","i"),N("br","branch",250,1110,"condExpr","a[i] > m"),N("setM","varset",480,1110,"name","m","valueExpr","a[i]"),N("out","output",20,1240,"outputExpr","m"),N("answer","sample_compare",250,1240,"exprMode","1"),N("sample","sample_input",250,20,"group","0")});E(g,"e","out","declN");E(g,"declN","out","inN");E(g,"inN","out","declA");E(g,"declA","out","declX");E(g,"declX","out","fill");E(g,"fill","body","inX");E(g,"inX","out","wset");E(g,"fill","done","declM");E(g,"declM","out","scan");E(g,"scan","body","br");E(g,"br","true","setM");E(g,"scan","done","out");return g;}
